package com.aoo.bcg.common.club;
import com.aoo.bcg.common.persistence.DriverManagerDataSource;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="AOO_DB_IT_URL",matches=".+")class ClubConcurrencyIntegrationTest{@Test void rejectsLostUpdateAndSerializesAggregatePhantoms()throws Exception{var source=new DriverManagerDataSource(System.getenv("AOO_DB_IT_URL"),System.getenv("AOO_DB_IT_USER"),System.getenv("AOO_DB_IT_PASSWORD"));var index=new JdbcClubMemberIndex(source,new ObjectMapper(),Clock.systemUTC());long club=System.currentTimeMillis(),player=club+1;Instant now=Instant.now();index.upsert(club,player,new ClubMemberRecord(club,player,ClubMemberRecord.Status.ACTIVE,ClubMemberRecord.Role.OWNER,true,Map.of(),now,now));var base=index.find(club,player).orElseThrow();var a=new ClubMemberRecord(club,player,ClubMemberRecord.Status.ACTIVE,ClubMemberRecord.Role.MANAGER,true,Map.of("writer","a"),now,now,base.revision());var b=new ClubMemberRecord(club,player,ClubMemberRecord.Status.SUSPENDED,ClubMemberRecord.Role.OWNER,false,Map.of("writer","b"),now,now,base.revision());try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);List<Future<Boolean>>writes=List.of(pool.submit(()->attempt(start,index,club,player,a)),pool.submit(()->attempt(start,index,club,player,b)));start.countDown();assertEquals(1,writes.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count());}assertEquals(base.revision()+1,index.find(club,player).orElseThrow().revision());try(var connection=source.getConnection();var statement=connection.prepareStatement("DELETE FROM aoo_club_member WHERE club_id=?")){statement.setLong(1,club);statement.executeUpdate();}}
private static boolean attempt(CountDownLatch start,JdbcClubMemberIndex index,long club,long player,ClubMemberRecord value)throws Exception{start.await();try{index.upsert(club,player,value);return true;}catch(IllegalStateException conflict){return false;}}}
